function normalizeList(value: unknown): string[] {
  if (Array.isArray(value))
    return value
      .map(String)
      .map(item => item.trim())
      .filter(Boolean);
  if (typeof value !== "string") return [];
  const trimmed = value.trim();
  if (!trimmed) return [];
  try {
    const parsed = JSON.parse(trimmed);
    if (Array.isArray(parsed))
      return parsed
        .map(String)
        .map(item => item.trim())
        .filter(Boolean);
  } catch {}
  return trimmed
    .split(",")
    .map(item => item.trim())
    .filter(Boolean);
}

function normalizeChainIds(value: unknown): number[] {
  const list = Array.isArray(value)
    ? value
    : typeof value === "string" && value.trim()
      ? value.split(",")
      : [];
  return list.map(item => Number(item)).filter(Number.isFinite);
}

function readStoredProfile(): StoredProfile | null {
  if (typeof window === "undefined") return null;
  const raw = walletGetItem("orderlyProfile");
  if (!raw) return null;
  try {
    return JSON.parse(raw) as StoredProfile;
  } catch {
    return null;
  }
}

