function EditModeModal({
  mode,
  form,
  onClose,
  onThemeChange,
  onOpenModal,
}: {
  mode: ThemeMode;
  form: DexConfigForm;
  onClose: () => void;
  onThemeChange: (theme: string) => void;
  onOpenModal: (modal: ThemeModal) => void;
}) {
  const { t } = useTranslation();
  const [selectedElement, setSelectedElement] = useState<HTMLElement | null>(
    null
  );
  const [selectedTargetId, _setSelectedTargetId] = useState(
    "--oui-color-primary"
  );
  const [isCtrlHeld, setIsCtrlHeld] = useState(false);
  const themeCSS = form.themeCSS || DEFAULT_THEME;
  const variables = parseCssVariables(themeCSS);

  useEffect(() => {
    if (mode !== "mobile") return;
    const originalMatchMedia = window.matchMedia.bind(window);
    window.matchMedia = (query: string) => {
      if (query === "(max-width: 768px)") {
        return {
          matches: true,
          media: query,
          onchange: null,
          addListener: () => undefined,
          removeListener: () => undefined,
          addEventListener: () => undefined,
          removeEventListener: () => undefined,
          dispatchEvent: () => true,
        } as MediaQueryList;
      }
      return originalMatchMedia(query);
    };
    return () => {
      window.matchMedia = originalMatchMedia;
    };
  }, [mode]);

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Control" || event.key === "Meta") setIsCtrlHeld(true);
      if (event.key === "Escape") setSelectedElement(null);
    }

    function handleKeyUp(event: KeyboardEvent) {
      if (event.key === "Control" || event.key === "Meta") setIsCtrlHeld(false);
    }

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
    };
  }, []);

  const selectedVariables = useMemo(() => {
    if (!selectedElement) return [];
    return extractThemeVariablesFromElement(selectedElement, themeCSS);
  }, [selectedElement, themeCSS]);
  const editableVariables = selectedVariables.length
    ? selectedVariables
    : [selectedTargetId];

  function updateVariable(variableName: string, value: string) {
    onThemeChange(updateCssVariable(themeCSS, variableName, value));
  }

  return (
    <div className="fixed inset-0 z-120 flex flex-col bg-[#0B0614] text-(--fg-primary)">
      <div className="flex min-h-16 shrink-0 flex-col gap-3 border-b border-(--line-subtle) bg-(--bg-surface-primary) px-5 py-3 lg:flex-row lg:items-center lg:justify-between">
        <div>
          <h2 className="text-lg font-semibold text-(--fg-primary)">
            {mode === "mobile"
              ? t("dexConfig.mobilePreview")
              : t("dexConfig.desktopPreview")}
          </h2>
          <p className="text-xs text-(--fg-secondary)">
            {t("dexConfig.inspectThemeVariablesHint")}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <ThemeHeaderButton
            label={t("dexConfig.presets")}
            icon={<Palette className="h-4 w-4" />}
            onClick={() => onOpenModal({ type: "presets", mode })}
          />
          <ThemeHeaderButton
            label={t("dexConfig.theme")}
            icon={<Settings2 className="h-4 w-4" />}
            onClick={() => onOpenModal({ type: "theme", mode })}
          />
          <ThemeHeaderButton
            label={t("dexConfig.ai")}
            icon={<Sparkles className="h-4 w-4" />}
            onClick={() => onOpenModal({ type: "ai", mode })}
          />
          <button
            type="button"
            onClick={onClose}
            className="flex h-9 items-center gap-2 rounded-lg border border-(--line-subtle) bg-(--bg-surface-secondary) px-3 text-xs font-medium text-(--fg-primary) transition hover:bg-(--bg-hover)"
          >
            {t("common.close")}
          </button>
        </div>
      </div>
      <div className="relative min-h-0 flex-1 overflow-hidden bg-black/40">
        {isCtrlHeld && (
          <style>{`[data-dex-edit-preview] * { cursor: crosshair !important; }`}</style>
        )}
        <div
          data-dex-edit-preview
          className={`h-full w-full ${mode === "mobile" ? "overflow-y-auto overflow-x-hidden p-4" : "overflow-hidden p-4"}`}
        >
          <LivePreview
            mode={mode}
            brokerName={form.brokerName}
            primaryLogo={form.primaryLogo}
            secondaryLogo={form.secondaryLogo}
            themeCSS={themeCSS}
            inspectMode
            onInspectElement={setSelectedElement}
          />
        </div>
        {selectedElement && (
          <div className="absolute bottom-5 right-5 z-10 max-h-[calc(100%-40px)] w-[min(390px,calc(100%-40px))] overflow-y-auto rounded-2xl border border-(--line-subtle) bg-[rgba(19,14,29,0.96)] p-4 shadow-[0_28px_90px_rgba(0,0,0,0.42)] backdrop-blur">
            <div className="mb-3 flex items-start justify-between gap-3">
              <div>
                <div className="text-sm font-medium text-(--fg-primary)">
                  {getElementLabel(selectedElement)}
                </div>
                <p className="mt-1 text-xs text-(--fg-secondary)">
                  {t("dexConfig.editDetectedVariables")}
                </p>
              </div>
              <button
                type="button"
                onClick={() => setSelectedElement(null)}
                className="rounded-md p-1 text-(--fg-secondary) hover:bg-(--bg-hover) hover:text-(--fg-primary)"
                aria-label={t("dexConfig.closeInspector")}
              >
                <X className="h-4 w-4" />
              </button>
            </div>
            <div className="space-y-2">
              {editableVariables.map(variableName => {
                const value = variables[variableName] || "0 0 0";
                return (
                  <label
                    key={variableName}
                    className="block rounded-lg border border-(--line-subtle) bg-(--bg-surface-primary) p-3 text-xs text-(--fg-secondary)"
                  >
                    <span>{variableName}</span>
                    <div className="mt-2 flex items-center gap-2">
                      {isColorValue(value) && (
                        <input
                          type="color"
                          value={rgbSpaceToHex(value)}
                          onChange={event =>
                            updateVariable(
                              variableName,
                              hexToRgbSpace(event.target.value)
                            )
                          }
                          className="h-8 w-10 cursor-pointer rounded border-0 bg-transparent"
                        />
                      )}
                      <TextInput
                        value={value}
                        onChange={event =>
                          updateVariable(variableName, event.target.value)
                        }
                        className="h-8 font-mono text-xs"
                      />
                    </div>
                  </label>
                );
              })}
            </div>
            <button
              type="button"
              onClick={() => onOpenModal({ type: "theme", mode })}
              className="mt-4 w-full rounded-lg border border-(--line-subtle) bg-(--bg-surface-primary) px-3 py-2 text-xs font-medium text-(--fg-primary) hover:bg-(--bg-hover)"
            >
              {t("dexConfig.openFullThemeEditor")}
            </button>
          </div>
        )}
        {!selectedElement && (
          <div className="pointer-events-none absolute bottom-5 left-1/2 z-10 -translate-x-1/2 rounded-full border border-(--line-subtle) bg-[rgba(19,14,29,0.84)] px-4 py-2 text-xs text-(--fg-secondary) shadow-xl backdrop-blur">
            {t("dexConfig.inspectPreviewHint")}
          </div>
        )}
      </div>
    </div>
  );
}

